class Solution {
public:
    int maxProductDifference(vector<int>& a) {
        int mx1 = INT_MIN, mx2 = INT_MIN;
        int mn1 = INT_MAX, mn2 = INT_MAX;

        for (int x : a) {
            if (x > mx1) {
                mx2 = mx1;
                mx1 = x;
            } else if (x > mx2) {
                mx2 = x;
            }

            if (x < mn1) {
                mn2 = mn1;
                mn1 = x;
            } else if (x < mn2) {
                mn2 = x;
            }
        }

        return (mx1 * mx2) - (mn1 * mn2);
    }
};

class Solution {
public:
    int buyChoco(vector<int>& p, int money) {
        int mn1 = INT_MAX, mn2 = INT_MAX;

        for (int x : p) {
            if (x < mn1) {
                mn2 = mn1;
                mn1 = x;
            } else if (x < mn2) {
                mn2 = x;
            }
        }

        int cost = mn1 + mn2;
        return (cost <= money ? money - cost : money);
    }
};

class Solution {
public:
    struct Activity {
        int start, finish;
    };

    bool compareActivities(const Activity& a, const Activity& b) {
        return a.finish < b.finish;
    }

    int maxActivities(vector<int>& start, vector<int>& finish) {
        int n = start.size();
        vector<Activity> a(n);
        for (int i = 0; i < n; ++i) {
            a[i] = {start[i], finish[i]};
        }
        sort(a.begin(), a.end(), compareActivities);

        int cnt = 1;
        int prevFinish = a[0].finish;

        for (int i = 1; i < n; ++i) {
            if (a[i].start >= prevFinish) {
                cnt++;
                prevFinish = a[i].finish;
            }
        }
        return cnt;
    }
};

class Solution {
public:
    struct Meeting {
        int start, end, id;
    };

    bool compareMeetings(const Meeting& a, const Meeting& b) {
        if (a.end != b.end) return a.end < b.end;
        return a.id < b.id;
    }

    vector<int> maxMeetings(vector<int>& start, vector<int>& end) {
        int n = start.size();
        vector<Meeting> m(n);
        for (int i = 0; i < n; ++i) {
            m[i] = {start[i], end[i], i + 1};
        }
        sort(m.begin(), m.end(), compareMeetings);

        vector<int> ans;
        ans.push_back(m[0].id);
        int prevEnd = m[0].end;

        for (int i = 1; i < n; ++i) {
            if (m[i].start > prevEnd) {
                ans.push_back(m[i].id);
                prevEnd = m[i].end;
            }
        }
        sort(ans.begin(), ans.end());
        return ans;
    }
};

class Solution {
public:
    int maxIceCream(vector<int>& costs, int coins) {
        sort(costs.begin(), costs.end());

        int ans = 0;
        for (int c : costs) {
            if (coins >= c) {
                coins -= c;
                ans++;
            } else {
                break;
            }
        }
        return ans;
    }
};

class Solution {
public:
    int maximumBags(vector<int>& capacity, vector<int>& rocks, int additionalRocks) {
        int n = capacity.size();
        vector<int> diff(n);
        for (int i = 0; i < n; ++i) {
            diff[i] = capacity[i] - rocks[i];
        }
        sort(diff.begin(), diff.end());

        int ans = 0;
        for (int d : diff) {
            if (additionalRocks >= d) {
                additionalRocks -= d;
                ans++;
            } else {
                break;
            }
        }
        return ans;
    }
};

class Solution {
