class Solution {
public:
    string smallestSubsequence(string s) {
        int last[26] = {0};
        bool inStack[26] = {false};
        int n = s.size();
        for (int i = 0; i < n; ++i) last[s[i] - 'a'] = i;

        string st = "";
        for (int i = 0; i < n; ++i) {
            int c = s[i] - 'a';
            if (inStack[c]) continue;

            while (!st.empty() && st.back() > s[i] && last[st.back() - 'a'] > i) {
                inStack[st.back() - 'a'] = false;
                st.pop_back();
            }

            st.push_back(s[i]);
            inStack[c] = true;
        }
        return st;
    }
};

class Solution {
public:
    int lastStoneWeight(vector<int>& stones) {
        priority_queue<int> pq(stones.begin(), stones.end());

        while (pq.size() > 1) {
            int y = pq.top(); pq.pop();
            int x = pq.top(); pq.pop();
            if (y != x) {
                pq.push(y - x);
            }
        }
        return pq.empty() ? 0 : pq.top();
    }
};

class Solution {
public:
    long long pickGifts(vector<int>& gifts, int k) {
        priority_queue<int> pq(gifts.begin(), gifts.end());

        while (k-- > 0 && !pq.empty()) {
            int top = pq.top();
            pq.pop();
            pq.push(floor(sqrt(top)));
        }

        long long sum = 0;
        while (!pq.empty()) {
            sum += pq.top();
            pq.pop();
        }
        return sum;
    }
};

class Solution {
public:
    bool isPossibleDivide(vector<int>& nums, int k) {
        if ((int)nums.size() % k != 0) return false;

        unordered_map<int, int> cnt;
        for (int x : nums) cnt[x]++;

        sort(nums.begin(), nums.end());

        for (int x : nums) {
            if (cnt[x] == 0) continue;
            for (int i = 0; i < k; ++i) {
                if (cnt[x + i] == 0) return false;
                cnt[x + i]--;
            }
        }
        return true;
    }
};

class Solution {
public:
    int pageFaults(int n, int c, vector<int>& pages) {
        list<int> lru;
        unordered_set<int> inCache;
        int faults = 0;

        for (int p : pages) {
            if (!inCache.count(p)) {
                faults++;
                if ((int)lru.size() == c) {
                    int evict = lru.back();
                    lru.pop_back();
                    inCache.erase(evict);
                }
                lru.push_front(p);
                inCache.insert(p);
            } else {
                lru.remove(p);
                lru.push_front(p);
            }
        }
        return faults;
    }
};

class Solution {
public:
    vector<int> minPartitionCoins(int n) {
        const int coins[] = {2000, 500, 200, 100, 50, 20, 10, 5, 2, 1};
        vector<int> ans;

        for (int c : coins) {
            while (n >= c) {
                ans.push_back(c);
                n -= c;
            }
        }
        return ans;
    }
};

class Solution {
public:
    vector<long long> egyptianFraction(long long nr, long long dr) {
        vector<long long> ans;

        while (nr != 0) {
            // ceil(dr / nr)
            long long x = (dr + nr - 1) / nr;
            ans.push_back(x);

            // nr/dr - 1/x = (nr * x - dr) / (dr * x)
            long long nextNr = nr * x - dr;
            long long nextDr = dr * x;

            long long g = std::gcd(nextNr, nextDr);
            nr = nextNr / g;
            dr = nextDr / g;
        }
        return ans;
    }
};
